// Expected values below were generated by executing the original Python
// source (octop_gateway/channels/feishu.py: _build_post_content,
// _guess_feishu_file_type, _extract_post_parts) on the same inputs.

// ---------------------------------------------------------------------------
// buildPostContent (Python feishu.py:626 _build_post_content)
// ---------------------------------------------------------------------------

func TestBuildPostContent(t *testing.T) {
	row := func(text string) [][]map[string]any {
		return [][]map[string]any{{{"tag": "md", "text": text}}}
	}
	cases := []struct {
		name string
		in   string
		want map[string]any
	}{
		{"plain", "hello", map[string]any{"zh_cn": map[string]any{"content": row("hello")}}},
		{"empty becomes marker", "", map[string]any{"zh_cn": map[string]any{"content": row("[empty]")}}},
		// fence right after a non-newline char gets a \n inserted
		{"fence mid-text", "a```b", map[string]any{"zh_cn": map[string]any{"content": row("a\n```b")}}},
		// fence already preceded by \n is left alone
		{"fence after newline", "a\n```", map[string]any{"zh_cn": map[string]any{"content": row("a\n```")}}},
		{"fence twice", "x```y```z", map[string]any{"zh_cn": map[string]any{"content": row("x\n```y\n```z")}}},
		// a leading fence has no preceding char and is unchanged
		{"fence at start", "```", map[string]any{"zh_cn": map[string]any{"content": row("```")}}},
		{"cjk before fence", "代码```块", map[string]any{"zh_cn": map[string]any{"content": row("代码\n```块")}}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := buildPostContent(tc.in)
			if !reflect.DeepEqual(got, tc.want) {
				t.Errorf("buildPostContent(%q)\n got %#v\nwant %#v", tc.in, got, tc.want)
			}
		})
	}
}

// ---------------------------------------------------------------------------
// guessFeishuFileType (Python feishu.py:893 _guess_feishu_file_type)
// ---------------------------------------------------------------------------

func TestGuessFeishuFileType(t *testing.T) {
	cases := []struct {
		filename string
		mime     string
		want     string
	}{
		{"a.opus", "audio/ogg", "opus"},
		{"a.OGG", "audio/ogg", "opus"}, // case-insensitive
		{"x.MP4", "video/mp4", "mp4"},
		{"v.avi", "video/x-msvideo", "mp4"},
		{"v.mov", "video/quicktime", "mp4"},
		{"v.mkv", "video/x-matroska", "mp4"},
		{"d.pdf", "application/pdf", "pdf"},
		{"d.doc", "application/msword", "doc"},
		{"d.docx", "application/vnd.openxmlformats-officedocument.wordprocessingml.document", "doc"},
		{"s.xls", "application/vnd.ms-excel", "xls"},
		{"s.xlsx", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", "xls"},
		{"p.ppt", "application/vnd.ms-powerpoint", "ppt"},
		{"p.pptx", "application/vnd.openxmlformats-officedocument.presentationml.presentation", "ppt"},
		{"noext", "application/octet-stream", "stream"}, // unknown extension fallback
		{"a.txt", "text/plain", "stream"},
		{"", "application/octet-stream", "stream"},           // empty filename
		{"archive.tar.gz", "application/gzip", "stream"},     // multi-suffix: only the last counts (and .gz is unmapped)
		{"doc", "application/msword", "stream"},              // bare word without dot is not an extension
	}
	for _, tc := range cases {
		if got := guessFeishuFileType(tc.filename, tc.mime); got != tc.want {
			t.Errorf("guessFeishuFileType(%q, %q) = %q, want %q", tc.filename, tc.mime, got, tc.want)
		}
	}
}

