func extractText(t *testing.T, contentData map[string]any, messageID string) (string, []imgateway.ContentPart) {
	t.Helper()
	return extractPostParts(contentData, messageID)
}

func TestExtractPostPartsTags(t *testing.T) {
	cases := []struct {
		name        string
		contentData map[string]any
		messageID   string
		wantText    string
		wantMedia   []imgateway.ContentPart // nil means "expect none"
	}{
		{"text tag", map[string]any{"content": []any{[]any{map[string]any{"tag": "text", "text": "Hello"}}}}, "m1", "Hello", nil},
		{"md tag", map[string]any{"content": []any{[]any{map[string]any{"tag": "md", "text": "md text"}}}}, "m1", "md text", nil},
		{"title", map[string]any{"title": "T", "content": []any{[]any{map[string]any{"tag": "text", "text": "Hello"}}}}, "m1", "T\nHello", nil},
		{"a with text", map[string]any{"content": []any{[]any{map[string]any{"tag": "a", "href": "https://x", "text": "link"}}}}, "m1", "link(https://x)", nil},
		{"a without text", map[string]any{"content": []any{[]any{map[string]any{"tag": "a", "href": "u"}}}}, "m1", "u(u)", nil},
		{"a without href", map[string]any{"content": []any{[]any{map[string]any{"tag": "a", "text": "t"}}}}, "m1", "t", nil},
		{"at user_name", map[string]any{"content": []any{[]any{map[string]any{"tag": "at", "user_name": "Bob"}}}}, "m1", "@Bob", nil},
		{"at user_id fallback", map[string]any{"content": []any{[]any{map[string]any{"tag": "at", "user_id": "u1"}}}}, "m1", "@u1", nil},
		{"emotion emoji_type", map[string]any{"content": []any{[]any{map[string]any{"tag": "emotion", "emoji_type": "SMILE"}}}}, "m1", "[SMILE]", nil},
		{"emotion emoji fallback", map[string]any{"content": []any{[]any{map[string]any{"tag": "emotion", "emoji": "OK"}}}}, "m1", "[OK]", nil},
		{"emotion default", map[string]any{"content": []any{[]any{map[string]any{"tag": "emotion"}}}}, "m1", "[emoji]", nil},
		{"img without message_id", map[string]any{"content": []any{[]any{map[string]any{"tag": "img", "image_key": "v3_imgkey"}}}}, "", "[Image: v3_imgkey]", nil},
		{"media without message_id", map[string]any{"content": []any{[]any{map[string]any{"tag": "media", "file_key": "fk1"}}}}, "", "[File: fk1]", nil},
		{"code_block with language", map[string]any{"content": []any{[]any{map[string]any{"tag": "code_block", "language": "go", "text": "x := 1"}}}}, "m1", "```go\nx := 1\n```", nil},
		{"code_block no language", map[string]any{"content": []any{[]any{map[string]any{"tag": "code_block", "text": "plain"}}}}, "m1", "```\nplain\n```", nil},
		{"nested zh_cn payload", map[string]any{"zh_cn": map[string]any{"title": "T", "content": []any{[]any{map[string]any{"tag": "text", "text": "Hi"}}}}}, "m1", "T\nHi", nil},
		{"multi paragraph join", map[string]any{"content": []any{
			[]any{map[string]any{"tag": "text", "text": "line1 "}, map[string]any{"tag": "emotion", "emoji_type": "OK"}},
			[]any{map[string]any{"tag": "text", "text": "line2"}},
		}}, "m1", "line1 [OK]\nline2", nil},
		{"empty payload", map[string]any{}, "m1", "", nil},
		{"unknown tag skipped", map[string]any{"content": []any{[]any{map[string]any{"tag": "bogus", "text": "x"}}}}, "m1", "", nil},
		{"non-dict element skipped", map[string]any{"content": []any{[]any{"junk", map[string]any{"tag": "text", "text": "ok"}}}}, "m1", "ok", nil},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			text, media := extractText(t, tc.contentData, tc.messageID)
			if text != tc.wantText {
				t.Errorf("text = %q, want %q", text, tc.wantText)
			}
			if len(media) != len(tc.wantMedia) {
				t.Fatalf("media count = %d, want %d", len(media), len(tc.wantMedia))
			}
		})
	}
}

func TestExtractPostPartsImgBecomesMedia(t *testing.T) {
	text, media := extractPostParts(
		map[string]any{"content": []any{[]any{map[string]any{"tag": "img", "image_key": "v3_imgkey"}}}},
		"om_123")
	if text != "" {
		t.Errorf("text = %q, want empty (img must not leak into text)", text)
	}
	if len(media) != 1 {
		t.Fatalf("media count = %d, want 1", len(media))
	}
	p := media[0]
	if p.Kind != imgateway.ContentTypeImage {
		t.Errorf("kind = %q, want image", p.Kind)
	}
	wantURL := "https://open.feishu.cn/open-apis/im/v1/messages/om_123/resources/v3_imgkey?type=image"
	if p.URL != wantURL {
		t.Errorf("url = %q, want %q", p.URL, wantURL)
	}
	if p.AltText != "v3_imgkey" {
		t.Errorf("alt_text = %q, want v3_imgkey", p.AltText)
	}
}

func TestExtractPostPartsMediaBecomesFile(t *testing.T) {
	_, media := extractPostParts(
		map[string]any{"content": []any{[]any{map[string]any{"tag": "media", "file_key": "fk1", "file_name": "doc.pdf"}}}},
		"om_9")
	if len(media) != 1 {
		t.Fatalf("media count = %d, want 1", len(media))
	}
	p := media[0]
	if p.Kind != imgateway.ContentTypeFile {
		t.Errorf("kind = %q, want file", p.Kind)
	}
	wantURL := "https://open.feishu.cn/open-apis/im/v1/messages/om_9/resources/fk1?type=file"
	if p.URL != wantURL {
		t.Errorf("url = %q, want %q", p.URL, wantURL)
	}
	if p.Filename != "doc.pdf" {
		t.Errorf("filename = %q, want doc.pdf", p.Filename)
	}
}

func TestExtractPostPartsTwoImages(t *testing.T) {
	_, media := extractPostParts(
		map[string]any{"content": []any{[]any{
			map[string]any{"tag": "img", "image_key": "k1"},
			map[string]any{"tag": "img", "image_key": "k2"},
		}}},
		"m")
	if len(media) != 2 {
		t.Fatalf("media count = %d, want 2", len(media))
	}
	base := "https://open.feishu.cn/open-apis/im/v1/messages/m/resources/"
	if media[0].URL != base+"k1?type=image" || media[1].URL != base+"k2?type=image" {
		t.Errorf("urls = %q, %q", media[0].URL, media[1].URL)
	}
}
